  "name": "tx_release_pool_buffer",
  "confidence": "medium",
  "docstring": "Releases the memory-pool buffer referenced by a TX descriptor when the descriptor flag is set and the buffer-owner/status bit indicates the buffer is not still in use, then clears the descriptor buffer pointer.",
  "subsystem": "mac",
  "var_renames": {
    "result": "tx_desc",
    "v1": "tx_desc_local"
  },
  "struct_hints": [
    {
      "offset": 4,
      "meaning": "TX descriptor flag or validity field (uint16)"
    },
    {
      "offset": 36,
      "meaning": "TX status/owner word; bit 0x00200000 gates whether the pool buffer can be freed"
    },
    {
      "offset": 72,
      "meaning": "pointer to memory-pool buffer associated with the TX descriptor"
    }
  ]
}
